arguments.command:
cd /home/runner/scratchpad/main-wt && for b in rachel monica phoebe joey chandler ross; do
  echo "=== $b ===";
  git log --format='%H' origin/friend/$b | while read sha; do
    msg=$(git show -s --format='%B' $sha);
    if echo "$msg" | grep -q 'Episode: S07/E07'; then echo "$sha"; fi;
  done;
done

cd /home/runner/scratchpad/main-wt && for sha in feb9d776c6e2ef4cf792f33880b6723f21ce8715 6f35074f677fb006ccbfdc50f1d20a500500d485 7b4353e82bbee3caf9f84e3cf7913e59f7684eee 5b4d421204e370ac436b20cc97298134ddefc491 6d167870dfb7b885e115292d221838efff48df07; do
  echo "===== $sha =====";
  git show -s --format='%ci%n%B' $sha;
done
